const fs = require('fs');

function extract(filename) {
  const buf = fs.readFileSync(filename);

  // Check ELF magic
  if (buf.readUInt32BE(0) !== 0x7f454c46) {
    console.error('Not an ELF file');
    return;
  }

  const is64 = buf.readUInt8(4) === 2;
  const isLE = buf.readUInt8(5) === 1;

  if (!is64 || !isLE) {
    console.error('Only 64-bit Little Endian ELF supported');
    return;
  }

  const e_phoff = Number(buf.readBigUInt64LE(32));
  const e_phentsize = buf.readUInt16LE(54);
  const e_phnum = buf.readUInt16LE(56);

  const result = {};

  // Check if addresses need base 0x400000
  // For PIE, vaddr starts at 0
  let baseAddress = 0;
  // Let's check first LOAD vaddr
  for (let i = 0; i < e_phnum; i++) {
    const phoff = e_phoff + i * e_phentsize;
    const p_type = buf.readUInt32LE(phoff);
    if (p_type === 1) { // PT_LOAD
      const p_vaddr = Number(buf.readBigUInt64LE(phoff + 16));
      if (p_vaddr === 0) {
        baseAddress = 0x400000;
      }
      break;
    }
  }

  for (let i = 0; i < e_phnum; i++) {
    const phoff = e_phoff + i * e_phentsize;
    const p_type = buf.readUInt32LE(phoff);
    if (p_type === 1) { // PT_LOAD
      const p_offset = Number(buf.readBigUInt64LE(phoff + 8));
      const p_vaddr = Number(buf.readBigUInt64LE(phoff + 16));
      const p_filesz = Number(buf.readBigUInt64LE(phoff + 32));
      const p_memsz = Number(buf.readBigUInt64LE(phoff + 40));

      const startAddr = p_vaddr + baseAddress;

      // Read file data
      const segmentData = Buffer.alloc(p_memsz);
      buf.copy(segmentData, 0, p_offset, p_offset + p_filesz);

      // Extract 32-bit ints aligned by 4
      for (let offset = 0; offset < p_memsz; offset += 4) {
        // Ensure 4-byte alignment relative to startAddr
        const addr = startAddr + offset;
        const val = segmentData.readInt32LE(offset);
        // Or readUInt32LE? Usually memory values can be signed or unsigned. Let's check if readInt32LE or readUInt32LE or both work. JSON numbers are floating point up to 2^53-1, so unsigned 32-bit fits perfectly.
        result[addr.toString()] = segmentData.readUInt32LE(offset);
      }
    }
  }

  console.log(JSON.stringify(result));
}

